/* Public reading list: local to this browser, never stores publisher credentials. */
(()=>{const KEY='dv-public-reading-list-v1';
 function clean(input){if(!Array.isArray(input))return [];const seen=new Set();return input.slice(0,100).flatMap(a=>{if(!a||typeof a.title!=='string'||typeof a.url!=='string'||!['gazzetta','repubblica'].includes(a.publisher))return [];let u;try{u=new URL(a.url);if(u.protocol!=='https:'||u.username||u.password||!['news.google.com','gazzetta.it','repubblica.it'].some(h=>u.hostname===h||u.hostname.endsWith('.'+h)))return []}catch{return []}if(seen.has(u.href))return [];seen.add(u.href);return [{title:a.title.slice(0,240),url:u.href,publisher:a.publisher,publishedAt:Number.isFinite(Date.parse(a.publishedAt))?new Date(a.publishedAt).toISOString():null}]})}
 function read(){try{const raw=localStorage.getItem(KEY);if(!raw||raw.length>200000)return [];return clean(JSON.parse(raw))}catch{return []}}
 function toggle(article){const item=clean([article])[0];if(!item)throw Error('Questo collegamento non può essere salvato.');const rows=read(),found=rows.some(x=>x.url===item.url);if(!found&&rows.length>=100)throw Error('Hai raggiunto 100 articoli salvati. Rimuovine uno per aggiungerne un altro.');const next=found?rows.filter(x=>x.url!==item.url):[item,...rows];localStorage.setItem(KEY,JSON.stringify(next));return {saved:!found,rows:next}}
 window.PressSaved={read,toggle,clean};})();
